import { assert, it, describe } from "@effect/vitest";
import {
  EventId,
  MessageId,
  PlanId,
  RunId,
  RuntimeRequestId,
  TurnItemId,
  type OrchestrationV2TurnItem,
  type OrchestrationV2Run,
  type OrchestrationV2ThreadHistoryPage,
  ProjectId,
  ProviderInstanceId,
  ThreadId,
  type OrchestrationV2DomainEvent,
} from "@t3tools/contracts";
import * as DateTime from "effect/DateTime";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as SqlClient from "effect/sql/SqlClient";
import * as Stream from "effect/Stream";

import * as SqlitePersistence from "../persistence/Sqlite.ts";
import * as ProjectionStore from "./ProjectionStore.ts";
import * as ProjectStore from "./ProjectStore.ts";
import * as EventStore from "./EventStore.ts";
import {
  encodeThreadHistoryCursor,
  selectHistoryPageFromCursor,
  THREAD_HISTORY_PAGE_POLICY,
} from "./threadHistoryPaging.ts";
import { projectTurnItemForWire } from "./WireProjection.ts";
import { findProjectedThreadItems } from "./ThreadFind.ts";

const layerTest = Layer.mergeAll(EventStore.layer, ProjectionStore.layer, ProjectStore.layer).pipe(
  Layer.provideMerge(SqlitePersistence.layerMemory),
);

const providerInstanceId = ProviderInstanceId.make("codex");
const at = (minute: number) => DateTime.makeUnsafe(Date.UTC(2026, 8, 27, 0, minute));

const createProject = (projectId: ProjectId) =>
  Effect.flatMap(ProjectStore.ProjectStoreV2, (projects) =>
    projects.apply({
      sequence: 0,
      eventId: EventId.make(`created:${projectId}`),
      aggregateKind: "project",
      aggregateId: projectId,
      occurredAt: DateTime.formatIso(at(0)),
      commandId: null,
      causationEventId: null,
      correlationId: null,
      metadata: {},
      type: "project.created",
      payload: {
        projectId,
        title: projectId,
        workspaceRoot: `/work/${projectId}`,
        defaultModelSelection: null,
        scripts: [],
        createdAt: DateTime.formatIso(at(0)),
        updatedAt: DateTime.formatIso(at(0)),
      },
    }),
  );

const thread = (
  threadId: ThreadId,
  projectId: ProjectId,
  overrides: { readonly archivedAt?: DateTime.Utc; readonly deletedAt?: DateTime.Utc } = {},
): OrchestrationV2DomainEvent => ({
  id: EventId.make(`created:${threadId}`),
  type: "thread.created",
  threadId,
  providerInstanceId,
  occurredAt: at(0),
  payload: {
    createdBy: "user",
    creationSource: "web",
    id: threadId,
    projectId,
    title: threadId,
    providerInstanceId,
    modelSelection: { instanceId: providerInstanceId, model: "gpt-5" },
    runtimeMode: "full-access",
    interactionMode: "default",
    branch: null,
    worktreePath: null,
    activeProviderThreadId: null,
    lineage: { parentThreadId: null, relationshipToParent: null, rootThreadId: threadId },
    forkedFrom: null,
    createdAt: at(0),
    updatedAt: at(0),
    archivedAt: overrides.archivedAt ?? null,
    settledOverride: null,
    settledAt: null,
    lastVisitedAt: null,
    deletedAt: overrides.deletedAt ?? null,
  },
});

const threadId = ThreadId.make("thread:find");
const projectId = ProjectId.make("project:find");
const runId = RunId.make("run:find");

function item(
  id: string,
  ordinal: number,
  text: string,
  kind: "user_message" | "assistant_message" | "proposed_plan" = "assistant_message",
  owner = threadId,
): Extract<
  OrchestrationV2TurnItem,
  { type: "user_message" | "assistant_message" | "proposed_plan" }
> {
  const base = {
    id: TurnItemId.make(id),
    threadId: owner,
    runId,
    nodeId: null,
    providerThreadId: null,
    providerTurnId: null,
    nativeItemRef: null,
    parentItemId: null,
    ordinal,
    status: "completed" as const,
    title: null,
    startedAt: at(100 - ordinal),
    completedAt: at(100 - ordinal),
    updatedAt: at(1),
  };
  if (kind === "proposed_plan")
    return { ...base, type: kind, planId: PlanId.make(id), markdown: text, streaming: false };
  if (kind === "user_message")
    return {
      ...base,
      type: kind,
      messageId: MessageId.make(id),
      text,
      inputIntent: "turn_start",
      attachments: [],
      createdBy: "user",
      creationSource: "web",
    };
  return { ...base, type: kind, messageId: MessageId.make(id), text, streaming: false };
}

function run(
  owner = threadId,
  id = runId,
  ordinal = 1,
  status: OrchestrationV2Run["status"] = "completed",
): Extract<OrchestrationV2DomainEvent, { type: "run.created" }> {
  return {
    id: EventId.make(`run:${owner}:${id}:${status}`),
    threadId: owner,
    occurredAt: at(1),
    type: "run.created",
    payload: {
      id,
      threadId: owner,
      ordinal,
      providerInstanceId,
      modelSelection: { instanceId: providerInstanceId, model: "gpt-6" },
      providerThreadId: null,
      userMessageId: MessageId.make("prompt"),
      rootNodeId: null,
      activeAttemptId: null,
      status,
      requestedAt: at(1),
      startedAt: at(1),
      completedAt: at(2),
      checkpointId: null,
      contextHandoffId: null,
    },
  };
}

const commit = Effect.fn("ThreadFindTest.commit")(function* (
  events: readonly OrchestrationV2DomainEvent[],
) {
  const store = yield* EventStore.EventStoreV2;
  const projection = yield* ProjectionStore.ProjectionStoreV2;
  yield* store.append({ events });
  yield* Effect.forEach(events, projection.apply, { discard: true });
});
const putItems = (items: readonly OrchestrationV2TurnItem[], version = "initial") =>
  commit(
    items.map((payload) => ({
      id: EventId.make(`${payload.threadId}:${payload.id}:${version}`),
      threadId: payload.threadId,
      occurredAt: at(1),
      type: "turn-item.updated" as const,
      payload,
    })),
  );
const setup = Effect.gen(function* () {
  yield* createProject(projectId);
  yield* commit([thread(threadId, projectId), run()]);
  return yield* ProjectionStore.ProjectionStoreV2;
});

describe("V2 thread find", () => {
  it.effect("navigates activity summaries and messages identically in SQLite and memory", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      const items: OrchestrationV2TurnItem[] = [
        item("prompt", 0, "Needle", "user_message"),
        {
          ...item("command", 1, ""),
          type: "command_execution",
          input: "printf 'ＮＥＥＤＬＥ needle'",
          output: "hidden output",
        },
        {
          ...item("thought", 2, ""),
          type: "reasoning",
          text: "Trace the needle",
          streaming: false,
        },
        { ...item("notice", 3, ""), type: "system_notice", message: "Needle warning" },
        item("plan", 4, "# Needle", "proposed_plan"),
        item("reply", 5, "A **needle** answer"),
        { ...item("setup", 6, ""), type: "command_execution", input: "Preparing workspace" },
        { ...item("empty-thought", 7, ""), type: "reasoning", text: "", streaming: false },
        {
          ...item("question", 8, ""),
          type: "user_input_request",
          requestId: RuntimeRequestId.make("answered"),
          questions: [],
          questionAnswer: {
            requestId: "answered",
            questionTextById: { q: "Which result?" },
            answers: { q: "needle" },
            attachmentsByQuestionId: {},
          },
        },
        item("async-answer:answered", 9, "needle", "user_message"),
      ];
      yield* putItems(items);
      const projected = items.map((item, position) => ({
        item,
        position,
        visibility: "local" as const,
        sourceThreadId: threadId,
        sourceItemId: item.id,
      }));
      const expected = [
        "prompt",
        "command",
        "command",
        "thought",
        "notice",
        "plan",
        "reply",
        "question",
      ];
      for (const [index, entryId] of expected.entries()) {
        const input = { threadId, query: "needle", index, includeActivity: true };
        const result = yield* projection.searchThread(input);
        assert.equal(result.totalMatches, expected.length);
        assert.equal(result.match?.entryId, entryId);
        assert.deepEqual(result.match, findProjectedThreadItems(projected, input, 0).match);
      }
      const wrapped = yield* projection.searchThread({
        threadId,
        query: "needle",
        includeActivity: true,
        start: { entryId: "prompt", occurrence: 0 },
        offset: -1,
      });
      assert.equal(wrapped.match?.entryId, "question");
      for (const query of ["hidden output", "Preparing workspace", "Thought"]) {
        const result = yield* projection.searchThread({ threadId, query, includeActivity: true });
        assert.equal(result.totalMatches, 0);
      }
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect("searches only renderable tool summaries, not hidden bodies or resource cards", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      const items: OrchestrationV2TurnItem[] = [
        {
          ...item("read", 0, ""),
          type: "dynamic_tool",
          toolName: "Read",
          input: { file_path: "/work/needle.ts" },
          output: "body-only",
        },
        {
          ...item("edit", 1, ""),
          type: "file_change",
          fileName: "needle.ts",
          diffStr: "body-only",
        },
        {
          ...item("web", 2, ""),
          type: "web_search",
          patterns: ["needle"],
          results: [{ url: "https://example.com", snippet: "body-only" }],
        },
        {
          ...item("large-input", 3, ""),
          type: "dynamic_tool",
          toolName: "Read",
          input: { file_path: "hidden-needle.ts", content: "x".repeat(20_000) },
        },
        {
          ...item("resource", 4, ""),
          type: "dynamic_tool",
          toolName: "html_render",
          input: {},
          output: { htmlRender: { attachmentId: "resource-1", title: "needle", height: 200 } },
        },
      ];
      yield* putItems(items);
      const legacy = yield* projection.searchThread({ threadId, query: "needle" });
      assert.equal(legacy.totalMatches, 0);
      assert.isUndefined(legacy.activityIncluded);
      const result = yield* projection.searchThread({
        threadId,
        query: "needle",
        includeActivity: true,
      });
      assert.equal(result.totalMatches, 3);
      assert.isTrue(result.activityIncluded);
      assert.deepEqual(
        result.navigation?.map((entry) => entry.entryId),
        ["read", "edit", "web"],
      );
      const hidden = yield* projection.searchThread({
        threadId,
        query: "body-only",
        includeActivity: true,
      });
      assert.equal(hidden.totalMatches, 0);
      const cachedLegacy = yield* projection.searchThread({ threadId, query: "needle" });
      assert.equal(cachedLegacy.totalMatches, 0);
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect("finishes one snapshot while later searches include newly inserted matches", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      yield* putItems([
        item("selected", 1, "snapshot needle"),
        item("last", 2, "snapshot last needle"),
      ]);
      const frames = yield* projection.searchThreadStream({ threadId, query: "needle" }).pipe(
        Stream.tap((frame) =>
          frame.complete === false
            ? putItems([item("inserted", 0, "snapshot inserted needle")], "during-search")
            : Effect.void,
        ),
        Stream.runCollect,
      );
      assert.equal(frames.length, 2);
      assert.equal(frames[1]!.totalMatches, 2);
      assert.deepEqual(frames[1]!.match, frames[0]!.match);
      const updated = yield* projection.searchThread({
        threadId,
        query: "needle",
        start: { entryId: "selected", occurrence: 0 },
      });
      assert.equal(updated.totalMatches, 3);
      assert.equal(updated.activeIndex, 1);
      assert.equal(updated.match?.entryId, "selected");
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect("returns bounded navigation counts around the selection, including wraparound", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      yield* putItems(
        Array.from({ length: 30 }, (_, i) =>
          item(`message:${i}`, i, "needle ".repeat((i % 3) + 1)),
        ),
      );
      const current = yield* projection.searchThread({
        threadId,
        query: "needle",
        start: { entryId: "message:14", occurrence: 1 },
      });
      assert.equal(current.totalMatches, 60);
      assert.equal(current.activeIndex, 28);
      assert.equal(current.navigation?.length, 17);
      assert.deepEqual(
        current.navigation?.map((entry) => entry.entryId),
        Array.from({ length: 17 }, (_, i) => `message:${i + 6}`),
      );
      assert.deepEqual(
        current.navigation?.find((entry) => entry.entryId === "message:14"),
        {
          entryId: "message:14",
          runId,
          startIndex: 27,
          count: 3,
        },
      );
      const first = yield* projection.searchThread({ threadId, query: "needle" });
      assert.equal(first.navigation?.length, 17);
      assert.include(first.navigation?.map((entry) => entry.entryId) ?? [], "message:29");
      const empty = yield* projection.searchThread({ threadId, query: "absent" });
      assert.deepEqual(empty.navigation, []);
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect("keeps navigation compact for a message with thousands of occurrences", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      yield* putItems([item("many", 1, "needle ".repeat(5000))]);
      const result = yield* projection.searchThread({ threadId, query: "needle", index: 2000 });
      assert.equal(result.totalMatches, 5000);
      assert.equal(result.match?.occurrence, 2000);
      assert.deepEqual(result.navigation, [{ entryId: "many", runId, startIndex: 0, count: 5000 }]);
      assert.isBelow(JSON.stringify(result).length, 500);
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect("cycles relative to the current match when new matches are inserted", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      yield* putItems([
        item("first", 10, "needle"),
        item("current", 20, "needle"),
        item("last", 30, "needle"),
      ]);
      const initial = yield* projection.searchThread({ threadId, query: "needle", index: 1 });
      assert.equal(initial.match?.entryId, "current");
      yield* putItems([
        item("new-before", 15, "needle"),
        item("new-after", 25, "needle"),
        item("new-last", 40, "needle"),
      ]);
      const start = { entryId: "current", occurrence: 0 };
      const refreshed = yield* projection.searchThread({ threadId, query: "needle", start });
      assert.equal(refreshed.totalMatches, 6);
      assert.equal(refreshed.activeIndex, 2);
      assert.equal(refreshed.match?.entryId, "current");
      const next = yield* projection.searchThread({ threadId, query: "needle", start, offset: 1 });
      assert.equal(next.match?.entryId, "new-after");
      const previous = yield* projection.searchThread({
        threadId,
        query: "needle",
        start,
        offset: -1,
      });
      assert.equal(previous.match?.entryId, "new-before");
      const end = yield* projection.searchThread({
        threadId,
        query: "needle",
        start: { entryId: "last", occurrence: 0 },
        offset: 1,
      });
      assert.equal(end.match?.entryId, "new-last");
      const wrapped = yield* projection.searchThread({
        threadId,
        query: "needle",
        start: { entryId: "new-last", occurrence: 0 },
        offset: 1,
      });
      assert.equal(wrapped.match?.entryId, "first");
      const backwards = yield* projection.searchThread({
        threadId,
        query: "needle",
        start: { entryId: "first", occurrence: 0 },
        offset: -1,
      });
      assert.equal(backwards.match?.entryId, "new-last");
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect("searches visible rendered messages and plans in canonical item order", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      yield* putItems([
        item("user", 1, "Check **the build**", "user_message"),
        item("assistant", 2, "check the build twice: check the build"),
        item("plan-item", 3, "# Check the build\nShip it", "proposed_plan"),
        item("url", 4, "[documentation](https://hidden.example/needle)"),
      ]);
      const matches = [];
      for (let index = 0; index < 4; index++) {
        const result = yield* projection.searchThread({
          threadId,
          query: "CHECK THE BUILD",
          index,
        });
        assert.equal(result.totalMatches, 4);
        matches.push(result.match);
      }
      assert.deepEqual(matches, [
        { entryId: "user", runId, occurrence: 0 },
        { entryId: "assistant", runId, occurrence: 0 },
        { entryId: "assistant", runId, occurrence: 1 },
        { entryId: "plan-item", runId, occurrence: 0 },
      ]);
      assert.equal(
        (yield* projection.searchThread({ threadId, query: "hidden.example" })).totalMatches,
        0,
      );
      assert.equal(
        (yield* projection.searchThread({ threadId, query: "check", index: 99 })).activeIndex,
        3,
      );
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect("searches displayed skill labels and invalidates parsed text when labels change", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      yield* putItems([item("skill", 1, "Use $test-t3-app now")]);
      const input = {
        threadId,
        query: "T3 App Testing",
        skills: [{ name: "test-t3-app", displayName: "T3 App Testing" }],
      };
      assert.equal((yield* projection.searchThread(input)).totalMatches, 1);
      assert.equal((yield* projection.searchThread({ ...input, skills: [] })).totalMatches, 0);
      yield* putItems(
        [item("skill-plan", 2, "# Verify\nUse $test-t3-app now", "proposed_plan")],
        "plan",
      );
      assert.equal((yield* projection.searchThread(input)).totalMatches, 1);
      assert.equal(
        (yield* projection.searchThread({ ...input, query: "$test-t3-app" })).totalMatches,
        1,
      );
      assert.equal((yield* projection.searchThread({ ...input, query: "App" })).totalMatches, 2);
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect("never mixes message versions when the searched thread changes during a scan", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      const sql = yield* SqlClient.SqlClient;
      const items = Array.from({ length: 260 }, (_, i) => item(`message:${i}`, i, "needle"));
      yield* putItems(items);
      const updated = items.map((item) =>
        item.type === "assistant_message" ? { ...item, text: "needle needle" } : item,
      );
      const [during] = yield* Effect.all(
        [
          projection.searchThread({ threadId, query: "needle" }),
          sql.withTransaction(putItems(updated, "concurrent")),
        ],
        { concurrency: "unbounded" },
      );
      assert.include([260, 520], during.totalMatches);
      assert.equal(
        (yield* projection.searchThread({ threadId, query: "needle" })).totalMatches,
        520,
      );
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect("starts at the reading position and wraps when no later match exists", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      yield* putItems([
        item("first", 1, "needle"),
        item("reading", 2, "needle above, needle below"),
        item("between", 3, "nothing"),
        item("last", 4, "needle"),
        item("end", 5, "nothing"),
      ]);
      const from = (entryId: string, occurrence = 0) =>
        projection.searchThread({ threadId, query: "needle", start: { entryId, occurrence } });
      assert.equal((yield* from("reading")).activeIndex, 1);
      const below = yield* from("reading", 1);
      assert.equal(below.activeIndex, 2);
      assert.equal(below.match?.occurrence, 1);
      assert.equal((yield* from("between")).match?.entryId, "last");
      assert.equal((yield* from("reading", 2)).activeIndex, 3);
      assert.equal((yield* from("end")).match?.entryId, "first");
      assert.equal((yield* from("missing")).activeIndex, 0);
      const explicit = yield* projection.searchThread({
        threadId,
        query: "needle",
        start: { entryId: "last", occurrence: 0 },
        index: 1,
      });
      assert.equal(explicit.match?.entryId, "reading");
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect("finds matches beyond the recent history window", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      const items = Array.from({ length: 520 }, (_, i) =>
        item(`message:${i}`, i + 1, i === 8 || i === 510 ? "sentinel" : "other message"),
      );
      yield* putItems(items);
      const first = yield* projection.searchThread({ threadId, query: "sentinel" });
      const last = yield* projection.searchThread({ threadId, query: "sentinel", index: 1 });
      assert.equal(first.totalMatches, 2);
      assert.equal(first.match?.entryId, "message:8");
      assert.equal(last.match?.entryId, "message:510");
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect("invalidates cached counts when streamed text changes or a run rolls back", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      const original = item("streaming", 1, "needle");
      yield* putItems([original]);
      assert.equal((yield* projection.searchThread({ threadId, query: "needle" })).totalMatches, 1);
      if (original.type !== "assistant_message") return;
      yield* putItems([{ ...original, text: "needle needle", streaming: true }], "streaming");
      assert.equal((yield* projection.searchThread({ threadId, query: "needle" })).totalMatches, 2);
      const updated = run(threadId, runId, 1, "rolled_back");
      yield* commit([{ ...updated, type: "run.updated" }]);
      assert.equal((yield* projection.searchThread({ threadId, query: "needle" })).totalMatches, 0);
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect(
    "does not search undispatched inputs, cancelled queue rows, or folded question answers",
    () =>
      Effect.gen(function* () {
        const projection = yield* setup;
        const queuedRunId = RunId.make("queued:cancelled");
        yield* commit([run(threadId, queuedRunId, 2, "cancelled")]);
        const queued = item("cancelled", 1, "needle", "user_message");
        if (queued.type !== "user_message") return;
        const answer = item("async-answer:question", 2, "needle", "user_message");
        const question: OrchestrationV2TurnItem = {
          ...item("question", 3, ""),
          type: "user_input_request",
          requestId: RuntimeRequestId.make("question"),
          questions: [],
          questionAnswer: { requestId: "question", answers: {}, attachmentsByQuestionId: {} },
        };
        yield* putItems([
          { ...queued, runId: queuedRunId, inputIntent: "queued_turn" },
          answer,
          question,
        ]);
        const event: OrchestrationV2DomainEvent = {
          id: EventId.make("undispatched"),
          threadId,
          occurredAt: at(2),
          type: "message.updated",
          payload: {
            id: MessageId.make("undispatched"),
            threadId,
            runId: null,
            nodeId: null,
            role: "user",
            text: "needle",
            attachments: [],
            streaming: false,
            createdBy: "user",
            creationSource: "web",
            createdAt: at(2),
            updatedAt: at(2),
          },
        };
        yield* commit([event]);
        const result = yield* projection.searchThread({ threadId, query: "needle" });
        assert.equal(result.totalMatches, 0);
        assert.isNull(result.match);
      }).pipe(Effect.provide(layerTest)),
  );

  it.effect(
    "searches inherited fork history through the fork boundary, using source item identities",
    () =>
      Effect.gen(function* () {
        const projection = yield* setup;
        const parent = ThreadId.make("thread:parent");
        const laterRun = RunId.make("run:later");
        const parentRun = RunId.make("run:parent");
        yield* commit([
          thread(parent, projectId),
          run(parent, parentRun),
          run(parent, laterRun, 2),
        ]);
        yield* putItems([
          { ...item("inherited", 1, "needle", "assistant_message", parent), runId: parentRun },
          { ...item("after-fork", 2, "needle", "assistant_message", parent), runId: laterRun },
        ]);
        const child = thread(threadId, projectId);
        if (child.type !== "thread.created") return;
        yield* commit([
          {
            ...child,
            id: EventId.make("child:fork"),
            type: "thread.metadata-updated",
            payload: {
              ...child.payload,
              forkedFrom: { type: "run", threadId: parent, runId: parentRun },
            },
          },
        ]);
        yield* putItems([item("local", 1, "needle")]);
        const inherited = yield* projection.searchThread({ threadId, query: "needle" });
        assert.equal(inherited.totalMatches, 2);
        assert.equal(inherited.match?.entryId, "inherited");
        assert.equal(
          (yield* projection.searchThread({ threadId, query: "needle", index: 1 })).match?.entryId,
          "local",
        );
        const snapshot = yield* projection.getThreadSnapshot(threadId);
        const history = yield* projection.getThreadHistoryPage(
          threadId,
          encodeThreadHistoryCursor({
            snapshotSequence: snapshot.snapshotSequence,
            sourceThreadId: threadId,
            sourceItemId: "local",
            position: 2,
          }),
        );
        assert.deepEqual(
          history.items,
          snapshot.projection.visibleTurnItems
            .slice(0, -1)
            .map((row) => ({ ...row, item: projectTurnItemForWire(row.item) })),
        );
        assert.equal(history.items[0]?.sourceThreadId, parent);
        assert.equal(history.items.at(-1)?.item.type, "fork");
        yield* putItems(
          [{ ...item("inherited", 1, "gone", "assistant_message", parent), runId: parentRun }],
          "parent-update",
        );
        assert.equal(
          (yield* projection.searchThread({ threadId, query: "needle" })).totalMatches,
          1,
        );
      }).pipe(Effect.provide(layerTest)),
  );

  it.effect("rejects deleted threads and keeps results scoped to their thread", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      const other = ThreadId.make("thread:other");
      yield* commit([thread(other, projectId), run(other, RunId.make("run:other"))]);
      yield* putItems([
        item("shared-id", 1, "needle"),
        item("other-id", 1, "other text", "assistant_message", other),
      ]);
      assert.equal((yield* projection.searchThread({ threadId, query: "needle" })).totalMatches, 1);
      assert.equal(
        (yield* projection.searchThread({ threadId: other, query: "needle" })).totalMatches,
        0,
      );
      const deleted = thread(threadId, projectId, { deletedAt: at(3) });
      if (deleted.type !== "thread.created") return;
      yield* commit([{ ...deleted, id: EventId.make("deleted"), type: "thread.deleted" }]);
      const error = yield* Effect.flip(projection.searchThread({ threadId, query: "needle" }));
      assert.equal(error._tag, "ProjectionStoreThreadNotFoundError");
      const historyError = yield* Effect.flip(
        projection.getThreadHistoryPage(
          threadId,
          encodeThreadHistoryCursor({
            snapshotSequence: 0,
            sourceThreadId: threadId,
            sourceItemId: "shared-id",
            position: 0,
          }),
        ),
      );
      assert.equal(historyError._tag, "ProjectionStoreThreadNotFoundError");
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect("invalidates a cached fork search when its empty source gains its first message", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      const parent = ThreadId.make("thread:empty-parent");
      const parentRun = RunId.make("run:empty-parent");
      yield* commit([thread(parent, projectId), run(parent, parentRun)]);
      const child = thread(threadId, projectId);
      if (child.type !== "thread.created") return;
      yield* commit([
        {
          ...child,
          id: EventId.make("child:empty-fork"),
          type: "thread.metadata-updated",
          payload: {
            ...child.payload,
            forkedFrom: { type: "run", threadId: parent, runId: parentRun },
          },
        },
      ]);
      yield* putItems([item("local", 1, "needle")]);
      assert.equal((yield* projection.searchThread({ threadId, query: "needle" })).totalMatches, 1);
      yield* putItems([
        { ...item("inherited", 1, "needle", "assistant_message", parent), runId: parentRun },
      ]);
      const updated = yield* projection.searchThread({ threadId, query: "needle" });
      assert.equal(updated.totalMatches, 2);
      assert.equal(updated.match?.entryId, "inherited");
    }).pipe(Effect.provide(layerTest)),
  );
});

describe("V2 history materialization", () => {
  it.effect(
    "combines history pages through a match's message identity without skipping intervening turns",
    () =>
      Effect.gen(function* () {
        const projection = yield* setup;
        const items = Array.from({ length: 45 }, (_, turn) => [
          item(`user:${turn}`, turn * 3, `turn ${turn}`, "user_message"),
          {
            ...item(`answer:${turn}`, turn * 3 + 1, `answer ${turn}`),
            messageId: MessageId.make(`message:${turn}`),
          },
          {
            ...item(`tool:${turn}`, turn * 3 + 2, ""),
            type: "command_execution" as const,
            input: "pwd",
            output: "huge output".repeat(1000),
            exitCode: 0,
          },
        ]).flat();
        yield* putItems(items);
        const snapshot = yield* projection.getThreadSnapshot(threadId);
        const cursor = encodeThreadHistoryCursor({
          snapshotSequence: snapshot.snapshotSequence,
          sourceThreadId: threadId,
          sourceItemId: "absent",
          position: items.length,
        });
        const ordinary = yield* projection.getThreadHistoryPage(threadId, cursor);
        assert.equal(ordinary.items[0]?.sourceItemId, "user:25");
        const targeted = yield* projection.getThreadHistoryPage(threadId, cursor, "message:10");
        assert.equal(targeted.items[0]?.sourceItemId, "user:10");
        assert.deepEqual(
          targeted.items.map((row) => row.sourceItemId),
          items.slice(30).map((entry) => entry.id),
        );
        const conversation = yield* projection.getThreadHistoryPage(
          threadId,
          cursor,
          "message:10",
          true,
        );
        assert.equal(conversation.nextCursor, targeted.nextCursor);
        assert.equal(conversation.hasMoreHistory, targeted.hasMoreHistory);
        assert.deepEqual(
          conversation.items.map((row) => row.sourceItemId),
          targeted.items
            .filter((row) => row.item.type !== "command_execution")
            .map((row) => row.sourceItemId),
        );
        assert.equal(conversation.items.length, 70);
        assert.equal(targeted.items.length, 105);
        assert.isTrue(targeted.hasMoreHistory);
        const earlier = yield* projection.getThreadHistoryPage(threadId, targeted.nextCursor!);
        assert.deepEqual(
          earlier.items.map((row) => row.sourceItemId),
          items.slice(0, 30).map((entry) => entry.id),
        );
        assert.isFalse(earlier.hasMoreHistory);
        const capped = yield* projection.getThreadHistoryPage(threadId, cursor, "message:0");
        assert.equal(capped.items[0]?.sourceItemId, "user:5");
        const absent = yield* projection.getThreadHistoryPage(
          threadId,
          cursor,
          "another-thread-message",
        );
        assert.deepEqual(absent, ordinary);
      }).pipe(Effect.provide(layerTest)),
  );

  it.effect("pages long turns without duplicating or skipping messages", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      const items = Array.from({ length: 45 }, (_, turn) => [
        item(`user:${turn}`, turn * 3, `turn ${turn}`, "user_message"),
        {
          ...item(`steer:${turn}`, turn * 3 + 1, "steer", "user_message"),
          inputIntent: "steer" as const,
        },
        item(
          `answer:${turn}`,
          turn * 3 + 2,
          turn === 40 ? "large ".repeat(200_000) : `answer ${turn}`,
        ),
      ]).flat();
      yield* putItems(items);
      const snapshot = yield* projection.getThreadSnapshot(threadId);
      const rows = snapshot.projection.visibleTurnItems.map((row) => ({
        ...row,
        item: projectTurnItemForWire(row.item),
      }));
      let cursor: string | null = encodeThreadHistoryCursor({
        snapshotSequence: snapshot.snapshotSequence,
        sourceThreadId: threadId,
        sourceItemId: "absent",
        position: rows.length,
      });
      const collected: string[] = [];
      while (cursor !== null) {
        const page: OrchestrationV2ThreadHistoryPage = yield* projection.getThreadHistoryPage(
          threadId,
          cursor,
        );
        assert.deepEqual(page, {
          snapshotSequence: snapshot.snapshotSequence,
          ...selectHistoryPageFromCursor({
            items: rows,
            cursor,
            snapshotSequence: snapshot.snapshotSequence,
          }),
        });
        // A turn larger than the byte budget is split, but only a lone oversized item may exceed it.
        assert.isTrue(
          page.items.length === 1 ||
            Buffer.byteLength(JSON.stringify(page.items), "utf8") <=
              THREAD_HISTORY_PAGE_POLICY.maxEncodedBytes,
        );
        collected.unshift(...page.items.map((row) => String(row.sourceItemId)));
        cursor = page.nextCursor;
      }
      assert.deepEqual(
        collected,
        items.map((entry) => String(entry.id)),
      );
    }).pipe(Effect.provide(layerTest)),
  );

  it.effect("enforces fallback item and byte limits and always admits an oversized row", () =>
    Effect.gen(function* () {
      const projection = yield* setup;
      yield* putItems(
        Array.from({ length: 80 }, (_, ordinal) =>
          item(`row:${ordinal}`, ordinal, ordinal < 78 ? "small" : "large ".repeat(200_000)),
        ),
      );
      const snapshot = yield* projection.getThreadSnapshot(threadId);
      const rows = snapshot.projection.visibleTurnItems.map((row) => ({
        ...row,
        item: projectTurnItemForWire(row.item),
      }));
      let cursor: string | null = encodeThreadHistoryCursor({
        snapshotSequence: snapshot.snapshotSequence,
        sourceThreadId: threadId,
        sourceItemId: "absent",
        position: rows.length,
      });
      const sizes: number[] = [];
      while (cursor !== null) {
        const page: OrchestrationV2ThreadHistoryPage = yield* projection.getThreadHistoryPage(
          threadId,
          cursor,
        );
        assert.deepEqual(page, {
          snapshotSequence: snapshot.snapshotSequence,
          ...selectHistoryPageFromCursor({
            items: rows,
            cursor,
            snapshotSequence: snapshot.snapshotSequence,
          }),
        });
        sizes.push(page.items.length);
        cursor = page.nextCursor;
      }
      assert.deepEqual(sizes, [1, 1, 75, 3]);
    }).pipe(Effect.provide(layerTest)),
  );
});

import {
  OrchestrationV2TurnItemJson,
  type OrchestrationV2ProjectedTurnItem,
  OrchestrationV2SearchThreadInput,
  type OrchestrationV2SearchThreadResult,
  type OrchestrationV2TurnItem,
  ThreadId,
  TurnItemId,
} from "@t3tools/contracts";
import {
  searchableMessageSegments,
  searchablePlanSegments,
  threadFindActivityText,
  THREAD_FIND_ACTIVITY_TYPES,
} from "@t3tools/shared/threadFindText";
import { countThreadSearchOccurrences } from "@t3tools/shared/threadSearch";
import * as Cache from "effect/Cache";
import * as Data from "effect/Data";
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";
import * as Stream from "effect/Stream";
import * as NodeSqliteClient from "@t3tools/shared/nodeSqliteClient";
import * as SqlClient from "effect/sql/SqlClient";
import {
  ProjectionStoreReadError,
  ProjectionStoreThreadNotFoundError,
  type ProjectionStoreV2Error,
} from "./ProjectionStore.ts";
import { projectTurnItemForWire } from "./WireProjection.ts";

interface FindRow {
  readonly position: number;
  readonly visibility: OrchestrationV2ProjectedTurnItem["visibility"];
  readonly sourceThreadId: ThreadId;
  readonly sourceItemId: TurnItemId;
}
interface FindPayload extends FindRow {
  readonly payload: string;
  readonly entryId: string;
  readonly type: OrchestrationV2TurnItem["type"];
}
interface FindDocument extends FindRow {
  readonly entryId: string;
  readonly runId: OrchestrationV2TurnItem["runId"];
  readonly count: number;
}
class TextKey extends Data.Class<{
  text: string;
  role: "user" | "assistant" | "plan" | "activity";
  streaming: boolean;
  hasContext: boolean;
  cwd: string | undefined;
  skills: NonNullable<OrchestrationV2SearchThreadInput["skills"]>;
}> {}

function textKey(
  item: OrchestrationV2TurnItem,
  cwd: string | undefined,
  skills: TextKey["skills"],
) {
  return new TextKey({
    text:
      item.type === "proposed_plan"
        ? item.markdown
        : item.type === "user_message" || item.type === "assistant_message"
          ? item.text
          : (threadFindActivityText(projectTurnItemForWire(item)) ?? ""),
    role:
      item.type === "proposed_plan"
        ? "plan"
        : item.type === "user_message"
          ? "user"
          : item.type === "assistant_message"
            ? "assistant"
            : "activity",
    streaming: item.type === "assistant_message" && item.streaming,
    hasContext: item.type === "user_message" && item.context !== undefined,
    cwd,
    skills,
  });
}

function parseText(key: TextKey): readonly string[] {
  if (key.role === "activity") return [key.text];
  return key.role === "plan"
    ? searchablePlanSegments(key.text, key.cwd)
    : (searchableMessageSegments(
        {
          role: key.role,
          text: key.text,
          streaming: key.streaming,
          context: key.hasContext ? { version: 1, records: [] } : undefined,
        },
        key.cwd,
        key.skills,
      ) ?? []);
}

function searchableRows(
  items: readonly OrchestrationV2ProjectedTurnItem[],
  includeActivity: boolean,
) {
  const foldedAnswers = new Set(
    items.flatMap(({ item }) =>
      item.type === "user_input_request" && item.questionAnswer
        ? [`async-answer:${item.questionAnswer.requestId}`]
        : [],
    ),
  );
  return items.filter(
    ({ item }) =>
      (["user_message", "assistant_message", "proposed_plan"].includes(item.type) ||
        (includeActivity && threadFindActivityText(item) !== null)) &&
      !(item.type === "user_message" && foldedAnswers.has(item.messageId)),
  );
}

function documentFor(row: OrchestrationV2ProjectedTurnItem, count: number): FindDocument {
  return {
    position: row.position,
    visibility: row.visibility,
    sourceThreadId: row.sourceThreadId,
    sourceItemId: row.sourceItemId,
    entryId:
      row.item.type === "user_message" || row.item.type === "assistant_message"
        ? row.item.messageId
        : row.item.id,
    runId: row.item.runId,
    count,
  };
}

function countSegments(segments: readonly string[], query: string) {
  return segments.reduce((sum, text) => sum + countThreadSearchOccurrences(text, query), 0);
}

function selectMatch(
  documents: readonly FindDocument[],
  input: Pick<OrchestrationV2SearchThreadInput, "index" | "start" | "offset">,
) {
  const totalMatches = documents.reduce((sum, doc) => sum + doc.count, 0);
  let requestedIndex = input.index ?? 0;
  if (input.index === undefined && input.start) {
    const startIndex = documents.findIndex((doc) => doc.entryId === input.start?.entryId);
    if (startIndex >= 0) {
      requestedIndex =
        documents.slice(0, startIndex).reduce((sum, doc) => sum + doc.count, 0) +
        Math.min(input.start.occurrence, documents[startIndex]!.count);
      if (requestedIndex >= totalMatches) requestedIndex = 0;
    }
  }
  const activeIndex =
    input.index === undefined && totalMatches > 0
      ? (((requestedIndex + (input.offset ?? 0)) % totalMatches) + totalMatches) % totalMatches
      : Math.min(requestedIndex, Math.max(0, totalMatches - 1));
  let occurrence = activeIndex;
  for (const document of documents) {
    if (occurrence < document.count) return { totalMatches, activeIndex, document, occurrence };
    occurrence -= document.count;
  }
  return { totalMatches, activeIndex, document: null, occurrence: 0 };
}

/** The memory projection uses the same match ordering as SQLite. */
export function findProjectedThreadItems(
  items: readonly OrchestrationV2ProjectedTurnItem[],
  input: OrchestrationV2SearchThreadInput,
  snapshotSequence: number,
  cwd?: string,
): OrchestrationV2SearchThreadResult {
  const rows = searchableRows(items, input.includeActivity === true);
  const docs = rows.map((row) =>
    documentFor(
      row,
      countSegments(parseText(textKey(row.item, cwd, input.skills ?? [])), input.query),
    ),
  );
  return resultForSelection(
    selectMatch(docs, input),
    docs,
    snapshotSequence,
    input.includeActivity,
  );
}

function resultForSelection(
  selected: ReturnType<typeof selectMatch>,
  documents: readonly FindDocument[],
  snapshotSequence: number,
  includeActivity = false,
): OrchestrationV2SearchThreadResult {
  let startIndex = 0;
  const entries = documents.flatMap(({ entryId, runId, count }) => {
    const entry = { entryId, runId, count, startIndex };
    startIndex += count;
    return count > 0 ? [entry] : [];
  });
  const selectedEntry = entries.findIndex((entry) => entry.entryId === selected.document?.entryId);
  const navigation =
    entries.length <= 17
      ? entries
      : Array.from(
          { length: 17 },
          (_, i) => entries[(selectedEntry + i - 8 + entries.length) % entries.length]!,
        );
  return {
    ...(includeActivity ? { activityIncluded: true as const } : {}),
    snapshotSequence,
    totalMatches: selected.totalMatches,
    activeIndex: selected.activeIndex,
    navigation,
    match:
      selected.document === null
        ? null
        : {
            entryId: selected.document.entryId,
            runId: selected.document.runId,
            occurrence: selected.occurrence,
          },
  };
}

export const makeThreadFind = Effect.fn("makeThreadFind")(function* (
  readIndex: (threadId: ThreadId) => Effect.Effect<
    readonly (Omit<FindRow, "position"> & {
      readonly item: Pick<OrchestrationV2TurnItem, "type">;
    })[],
    ProjectionStoreV2Error
  >,
) {
  const sql = yield* SqlClient.SqlClient;
  const encodeCacheKey = Schema.encodeEffect(
    Schema.fromJsonString(
      Schema.Struct({
        threadId: ThreadId,
        cwd: Schema.optional(Schema.String),
        query: Schema.String,
        skills: OrchestrationV2SearchThreadInput.fields.skills,
        includeActivity: Schema.Boolean,
      }),
    ),
  );
  const encodeThreadIds = Schema.encodeEffect(Schema.fromJsonString(Schema.Array(ThreadId)));
  const encodeSources = Schema.encodeEffect(
    Schema.fromJsonString(Schema.Array(Schema.Struct({ threadId: ThreadId, id: TurnItemId }))),
  );
  const decodeItem = Schema.decodeUnknownEffect(Schema.fromJsonString(OrchestrationV2TurnItemJson));
  const isSnapshotError = Schema.is(
    Schema.Union([ProjectionStoreReadError, ProjectionStoreThreadNotFoundError]),
  );
  const load = Effect.fn("ThreadFind.load")(function* (
    threadId: ThreadId,
    rows: readonly FindRow[],
  ) {
    if (rows.length === 0) return [];
    const sources = yield* encodeSources(
      rows.map((row) => ({ threadId: row.sourceThreadId, id: row.sourceItemId })),
    ).pipe(Effect.mapError((cause) => new ProjectionStoreReadError({ threadId, cause })));
    const payloads = yield* sql<{
      thread_id: string;
      turn_item_id: string;
      payload_json: string;
      entry_id: string;
      item_type: OrchestrationV2TurnItem["type"];
    }>`
      SELECT item.thread_id, item.turn_item_id,
        CASE item.type
          WHEN 'command_execution' THEN json_remove(item.payload_json, '$.output')
          WHEN 'file_change' THEN json_remove(item.payload_json, '$.diffStr', '$.oldStr', '$.newStr')
          WHEN 'file_search' THEN json_remove(item.payload_json, '$.results')
          WHEN 'web_search' THEN json_remove(item.payload_json, '$.results')
          ELSE item.payload_json
        END AS payload_json,
        CASE WHEN item.type IN ('user_message', 'assistant_message')
          THEN json_extract(item.payload_json, '$.messageId')
          ELSE item.turn_item_id END AS entry_id,
        json_extract(item.payload_json, '$.type') AS item_type
      FROM orchestration_v2_projection_turn_items AS item
      JOIN json_each(${sources}) AS wanted
        ON item.thread_id = json_extract(wanted.value, '$.threadId')
          AND item.turn_item_id = json_extract(wanted.value, '$.id')
    `.pipe(Effect.mapError((cause) => new ProjectionStoreReadError({ threadId, cause })));
    const byThread = new Map<string, Map<string, (typeof payloads)[number]>>();
    for (const row of payloads) {
      let items = byThread.get(row.thread_id);
      if (!items) byThread.set(row.thread_id, (items = new Map()));
      items.set(row.turn_item_id, row);
    }
    return yield* Effect.forEach(rows, (row) => {
      const payload = byThread.get(row.sourceThreadId)?.get(row.sourceItemId);
      return payload === undefined
        ? Effect.fail(new ProjectionStoreReadError({ threadId }))
        : Effect.succeed({
            ...row,
            payload: payload.payload_json,
            entryId: payload.entry_id,
            type: payload.item_type,
          });
    });
  });
  // Scans visit every message; a cache smaller than the thread churns without hits.
  const textCache = yield* Cache.make({
    capacity: 8192,
    timeToLive: "1 minute",
    lookup: (key: TextKey) => Effect.sync(() => parseText(key)),
  });
  // Bounded separately because each entry can hold a large body; typing reuses the parse.
  const largeTextCache = yield* Cache.make({
    capacity: 32,
    timeToLive: "1 minute",
    lookup: (key: TextKey) => Effect.sync(() => parseText(key)),
  });
  const scans = new Map<
    string,
    {
      sequence: number;
      documents: readonly FindDocument[];
      sourceThreadIds: readonly ThreadId[];
    }
  >();
  const readRevision = Effect.fn("ThreadFind.readRevision")(function* (
    threadIds: readonly ThreadId[],
  ) {
    const sources = yield* encodeThreadIds(threadIds);
    const revision = yield* sql<{ sequence: number }>`
      WITH RECURSIVE source_threads(thread_id) AS (
        SELECT value FROM json_each(${sources})
        UNION
        SELECT json_extract(t.payload_json, '$.forkedFrom.threadId')
        FROM orchestration_v2_projection_threads t
        JOIN source_threads s ON s.thread_id = t.thread_id
        WHERE json_extract(t.payload_json, '$.forkedFrom.type') = 'run'
      )
      SELECT COALESCE(MAX(sequence), 0) AS sequence FROM orchestration_events
      -- The planner otherwise walks every V2 event backwards from the newest,
      -- which takes seconds for a thread that has been idle a long time.
      INDEXED BY idx_orch_events_stream_sequence
      WHERE application_event_version = 2 AND aggregate_kind = 'thread'
        AND stream_id IN (SELECT thread_id FROM source_threads)
    `;
    return revision[0]?.sequence ?? 0;
  });
  const snapshot = Effect.fn("ThreadFind.snapshot")(
    function* (input: OrchestrationV2SearchThreadInput) {
      const { threadId } = input;
      const active = yield* sql<{ cwd: string | null }>`
      SELECT COALESCE(json_extract(t.payload_json, '$.worktreePath'), p.workspace_root) AS cwd
      FROM orchestration_v2_projection_threads t JOIN projection_projects p ON p.project_id = t.project_id
      WHERE t.thread_id = ${threadId} AND t.deleted_at IS NULL AND p.deleted_at IS NULL
    `;
      if (!active[0]) return yield* new ProjectionStoreThreadNotFoundError({ threadId });
      const cwd = active[0].cwd ?? undefined;
      const cacheKey = yield* encodeCacheKey({
        threadId,
        cwd,
        query: input.query,
        skills: input.skills ?? [],
        includeActivity: input.includeActivity === true,
      });
      const cached = scans.get(cacheKey);
      if (cached && cached.sequence === (yield* readRevision(cached.sourceThreadIds))) {
        const selected = selectMatch(cached.documents, input);
        scans.delete(cacheKey);
        scans.set(cacheKey, cached);
        return {
          result: resultForSelection(
            selected,
            cached.documents,
            cached.sequence,
            input.includeActivity,
          ),
        };
      }
      const index = yield* readIndex(threadId);
      const sourceThreadIds = [...new Set([threadId, ...index.map((row) => row.sourceThreadId)])];
      const sequence = yield* readRevision(sourceThreadIds);
      const candidates = index
        .map((row, position) => ({ ...row, position }))
        .filter(
          (row) =>
            ["user_message", "assistant_message", "proposed_plan", "user_input_request"].includes(
              row.item.type,
            ) ||
            (input.includeActivity === true && THREAD_FIND_ACTIVITY_TYPES.has(row.item.type)),
        );
      const payloads: FindPayload[] = [];
      for (let start = 0; start < candidates.length; start += 128) {
        payloads.push(...(yield* load(threadId, candidates.slice(start, start + 128))));
      }
      return { payloads, cwd, sequence, cacheKey, sourceThreadIds };
    },
    (effect) => sql.withTransaction(effect).pipe(NodeSqliteClient.readOnly),
    (effect, input) =>
      effect.pipe(
        Effect.mapError((cause) =>
          isSnapshotError(cause)
            ? cause
            : new ProjectionStoreReadError({ threadId: input.threadId, cause }),
        ),
      ),
  );
  const searchThreadStream = (input: OrchestrationV2SearchThreadInput) =>
    Stream.unwrap(
      Effect.gen(function* () {
        // Release SQLite before decoding and parsing. Both frames describe one snapshot.
        const data = yield* snapshot(input);
        if (data.result) return Stream.succeed(data.result);
        const { payloads, cwd, sequence, cacheKey, sourceThreadIds } = data;
        const decode = (row: FindPayload) =>
          decodeItem(row.payload).pipe(
            Effect.map((item) => ({ ...row, item })),
            Effect.mapError(
              (cause) => new ProjectionStoreReadError({ threadId: input.threadId, cause }),
            ),
          );
        // Answers rendered inside question cards must not appear as separate matches.
        const foldedAnswers = new Set<string>();
        for (const payload of payloads) {
          if (payload.type !== "user_input_request") continue;
          const { item } = yield* decode(payload);
          if (item.type === "user_input_request" && item.questionAnswer)
            foldedAnswers.add(`async-answer:${item.questionAnswer.requestId}`);
        }
        const rows = payloads.filter(
          (row) =>
            (row.type !== "user_input_request" || input.includeActivity === true) &&
            !(row.type === "user_message" && foldedAnswers.has(row.entryId)),
        );
        const documents = new Map<number, FindDocument>();
        const count = Effect.fnUntraced(function* (row: FindPayload) {
          const cached = documents.get(row.position);
          if (cached) return cached;
          const decoded = yield* decode(row);
          const key = textKey(decoded.item, cwd, input.skills ?? []);
          const segments = yield* Cache.get(
            key.text.length <= 32_768 ? textCache : largeTextCache,
            key,
          );
          const document = documentFor(decoded, countSegments(segments, input.query));
          documents.set(row.position, document);
          yield* Effect.yieldNow;
          return document;
        });
        const finish = Effect.gen(function* () {
          for (const row of rows) yield* count(row);
          const ordered = rows.map((row) => documents.get(row.position)!);
          scans.delete(cacheKey);
          scans.set(cacheKey, { sequence, documents: ordered, sourceThreadIds });
          if (scans.size > 8) {
            const oldest = scans.keys().next().value;
            if (oldest !== undefined) scans.delete(oldest);
          }
          return resultForSelection(
            selectMatch(ordered, input),
            ordered,
            sequence,
            input.includeActivity,
          );
        });
        if (input.index !== undefined || (input.offset ?? 0) !== 0)
          return Stream.fromEffect(finish);
        const anchor = Math.max(
          0,
          rows.findIndex((row) => row.entryId === input.start?.entryId),
        );
        for (let step = 0; step <= rows.length; step++) {
          const index = (anchor + step) % rows.length;
          const row = rows[index];
          if (!row) break;
          const document = yield* count(row);
          const occurrence =
            step === 0 && row.entryId === input.start?.entryId
              ? Math.min(input.start.occurrence, document.count)
              : 0;
          if (occurrence >= document.count) continue;
          const first: OrchestrationV2SearchThreadResult = {
            ...(input.includeActivity ? { activityIncluded: true as const } : {}),
            complete: false,
            snapshotSequence: sequence,
            totalMatches: 1,
            activeIndex: 0,
            match: { entryId: document.entryId, runId: document.runId, occurrence },
          };
          return Stream.concat(Stream.succeed(first), Stream.fromEffect(finish));
        }
        return Stream.fromEffect(finish);
      }),
    );
  return {
    searchThreadStream,
    searchThread: (input: OrchestrationV2SearchThreadInput) =>
      searchThreadStream(input).pipe(
        Stream.runCollect,
        Effect.map((results) => results[results.length - 1]!),
      ),
  };
});

