                parseRawHtml={false}
                extraRemarkPlugins={[[remarkThoughtPreview, "Thought"]]}
              />
            </span>
          }
          wrapLabel
        />
      ) : null}
      <LiveActivityRow
        label={
          thoughtIsStatus ? (
            row.active ? (
