import type { InlineSkill } from "@t3tools/shared/inlineSkills";
import type { OrchestrationV2SearchThreadResult, ScopedThreadRef } from "@t3tools/contracts";
import { scopedThreadKey } from "@t3tools/client-runtime/environment";
import { useEffect, useEffectEvent, useRef, useState } from "react";
import { orchestrationEnvironment } from "~/state/orchestration";
import { useThreadProjection } from "~/state/entities";
import { useEnvironmentQuery } from "~/state/query";
import { useDebouncedValue } from "~/state/queries";
import { type ThreadFindMatch, type ThreadFindStart, stepThreadFindIndex } from "./threadFind";
import {
  CLOSED_THREAD_FIND,
  closeThreadFind,
  setThreadFindQuery,
  useThreadFindOpen,
  useThreadFindStore,
  type ThreadFindLocalSelection,
  type ThreadFindState,
} from "./threadFindStore";

const EMPTY_SKILLS: readonly InlineSkill[] = [];

export function useThreadFind({
  thread,
  enabled,
  progressive = false,
  skills = EMPTY_SKILLS,
}: {
  thread: ScopedThreadRef | null;
  enabled: boolean;
  progressive?: boolean;
  skills?: readonly InlineSkill[];
}) {
  // Read here rather than passed in: a streamed delta re-renders only the find
  // provider, which refreshes open results from it.
  const content = useThreadProjection(enabled ? thread : null)?.projection;
  const lastContentRef = useRef(content);
  const refreshTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const refreshAfterSearchRef = useRef(false);
  const threadKey = thread ? scopedThreadKey(thread) : null;
  const isOpen = useThreadFindOpen(thread, enabled);
  const stored = useThreadFindStore();
  const state = isOpen ? stored : CLOSED_THREAD_FIND;
  const setState = (update: (previous: ThreadFindState) => Partial<ThreadFindState>) =>
    useThreadFindStore.setState((previous) =>
      previous.threadKey === threadKey ? update(previous) : previous,
    );

  const remote = useServerResults(
    isOpen ? thread : null,
    state.query,
    state.offset,
    state.requestId,
    state.start,
    skills,
    progressive,
  );
  const status: "loading" | "error" | null = remote.error
    ? "error"
    : remote.isPending && remote.data === null
      ? "loading"
      : null;
  const localSelection = rebaseLocalSelection(
    state.localSelection,
    remote.data,
    remote.navigationId,
  );
  const count = remote.data?.totalMatches ?? 0;
  const activeIndex = localSelection?.activeIndex ?? remote.data?.activeIndex ?? 0;
  const selectedMatch = localSelection?.match ?? remote.data?.match;
  const entryId = selectedMatch?.entryId;
  const runId = selectedMatch?.runId;
  const occurrence = selectedMatch?.occurrence;
  const counting = remote.data?.complete === false;
  const navigationId = localSelection?.navigationId ?? remote.navigationId;
  const findExpanded = isOpen && state.query.trim().length > 0;
  const findQuery = isOpen && remote.data?.match ? state.query : "";
  const nextTimeline: TimelineFields = {
    findOpen: isOpen,
    findExpanded,
    findActivity: remote.data?.activityIncluded === true,
    findQuery,
    activeFindMatch:
      entryId !== undefined && occurrence !== undefined
        ? { entryId, runId: runId ?? null, occurrence }
        : null,
    findNavigationId: navigationId,
  };
  // Keep timeline identity stable during count and response updates to avoid extra jumps.
  const [storedTimeline, setTimeline] = useState(nextTimeline);
  let timeline = storedTimeline;
  if (!sameTimeline(timeline, nextTimeline)) {
    timeline = nextTimeline;
    setTimeline(timeline);
  }
  const match = timeline.activeFindMatch;
  const step = (delta: number) => {
    if (count === 0 || counting) return;
    setState((previous) => {
      const local = rebaseLocalSelection(previous.localSelection, remote.data, remote.navigationId);
      const pending = previous.navigationId !== (local?.navigationId ?? remote.navigationId);
      const selected = local?.match ?? remote.data?.match;
      const nextIndex = stepThreadFindIndex(
        local?.activeIndex ?? remote.data?.activeIndex ?? 0,
        count,
        delta,
      );
      const entry = remote.data?.navigation?.find(
        (entry) => nextIndex >= entry.startIndex && nextIndex < entry.startIndex + entry.count,
      );
      const nextNavigationId = previous.navigationId + 1;
      if (
        !pending &&
        !remote.isPending &&
        entry &&
        remote.data &&
        (!local ||
          local.base === remote.data ||
          remote.data.navigation?.some(
            (entry) =>
              entry.entryId === local.match.entryId && local.match.occurrence < entry.count,
          )) &&
        refreshTimerRef.current === null &&
        lastContentRef.current === content
      ) {
        return {
          ...previous,
          navigationId: nextNavigationId,
          localSelection: {
            base: remote.data,
            baseNavigationId: remote.navigationId,
            activeIndex: nextIndex,
            match: {
              entryId: entry.entryId,
              runId: entry.runId,
              occurrence: nextIndex - entry.startIndex,
            },
            navigationId: nextNavigationId,
          },
        };
      }
      return {
        ...previous,
        start:
          pending || !selected
            ? previous.start
            : { entryId: selected.entryId, occurrence: selected.occurrence },
        offset: pending ? previous.offset + delta : delta,
        navigationId: nextNavigationId,
        requestId: nextNavigationId,
      };
    });
  };

  // Runs from the refresh timer and after a coalesced search settles, against
  // the results and selection showing by then.
  const refreshLiveResults = useEffectEvent(() => {
    if (!isOpen || !state.query.trim()) return;
    // Coalesce paging updates while the server counts to avoid restarting scans.
    if (progressive && remote.isPending) {
      refreshAfterSearchRef.current = true;
      return;
    }
    if (!match || state.navigationId !== navigationId) {
      remote.refresh();
      return;
    }
    const start = { entryId: match.entryId, occurrence: match.occurrence };
    if (
      state.offset === 0 &&
      state.start?.entryId === start.entryId &&
      state.start.occurrence === start.occurrence &&
      state.requestId === state.navigationId
    ) {
      remote.refresh();
    } else {
      setState((previous) => ({
        ...previous,
        start,
        offset: 0,
        requestId: previous.navigationId,
      }));
    }
  });
  useEffect(() => {
    if (!refreshAfterSearchRef.current || remote.isPending) return;
    refreshAfterSearchRef.current = false;
    if (!remote.error) refreshLiveResults();
  }, [remote.isPending, remote.error]);
  useEffect(() => {
    if (lastContentRef.current === content) return;
    lastContentRef.current = content;
    if (!isOpen || !state.query.trim() || refreshTimerRef.current !== null) return;
    refreshTimerRef.current = setTimeout(() => {
      refreshTimerRef.current = null;
      refreshLiveResults();
    }, 300);
  }, [content, isOpen, state.query]);
  useEffect(() => {
    if (!isOpen || threadKey === null || !state.query.trim()) return;
    return () => {
      if (refreshTimerRef.current !== null) clearTimeout(refreshTimerRef.current);
      refreshTimerRef.current = null;
      refreshAfterSearchRef.current = false;
    };
  }, [threadKey, isOpen, state.query]);

  return {
    barProps: {
      open: isOpen,
      query: state.query,
      matchCount: count,
      counting,
      activeIndex,
      status,
      focusRequestId: state.focusRequestId,
      onRetry: remote.refresh,
      onQueryChange: (query: string) => {
        if (threadKey !== null) setThreadFindQuery(threadKey, query);
      },
      onNext: () => step(1),
      onPrevious: () => step(-1),
      onClose: closeThreadFind,
    },
    timelineProps: timeline,
  };
}

export interface TimelineFields {
  readonly findOpen: boolean;
  readonly findExpanded: boolean;
  readonly findActivity: boolean;
  readonly findQuery: string;
  readonly activeFindMatch: ThreadFindMatch | null;
  readonly findNavigationId: number;
}

function sameTimeline(a: TimelineFields, b: TimelineFields) {
  const aMatch = a.activeFindMatch;
  const bMatch = b.activeFindMatch;
  return (
    a.findOpen === b.findOpen &&
    a.findExpanded === b.findExpanded &&
    a.findActivity === b.findActivity &&
    a.findQuery === b.findQuery &&
    a.findNavigationId === b.findNavigationId &&
    (aMatch === null || bMatch === null
      ? aMatch === bMatch
      : aMatch.entryId === bMatch.entryId &&
        aMatch.runId === bMatch.runId &&
        aMatch.occurrence === bMatch.occurrence)
  );
}

function rebaseLocalSelection(
  selection: ThreadFindLocalSelection | null,
  data: OrchestrationV2SearchThreadResult | null,
  navigationId: number,
) {
  if (!selection || !data) return null;
  if (selection.base === data && selection.baseNavigationId === navigationId) return selection;
  if (navigationId >= selection.navigationId) return null;
  const entry = data.navigation?.find((entry) => entry.entryId === selection.match.entryId);
  if (!entry || selection.match.occurrence >= entry.count) return selection;
  const activeIndex = entry.startIndex + selection.match.occurrence;
  return activeIndex === selection.activeIndex ? selection : { ...selection, activeIndex };
}

function useServerResults(
  thread: ScopedThreadRef | null,
  query: string,
  offset: number,
  navigationId: number,
  start: ThreadFindStart | undefined,
  skills: readonly InlineSkill[],
  progressive: boolean,
) {
  const skillLabels = skills.map(({ name, displayName }) => ({ name, displayName }));
  const normalizedQuery = query.trim();
  const debouncedQuery = useDebouncedValue(normalizedQuery, 100);
  const environmentId = thread?.environmentId;
  const threadId = thread?.threadId;
  const target =
    environmentId && threadId && debouncedQuery && normalizedQuery === debouncedQuery
      ? {
          environmentId,
          input: {
            threadId,
            query: debouncedQuery,
            includeActivity: true,
            ...(start ? { start } : {}),
            ...(offset !== 0 ? { offset } : {}),
            skills: skillLabels,
          },
        }
      : null;
  const targetKey = target ? JSON.stringify([progressive, target]) : null;
  const [storedAtom, setStoredAtom] = useState(() => ({
    key: targetKey,
    atom: resolveThreadFindAtom(target, progressive),
  }));
  let atom = storedAtom.atom;
  if (storedAtom.key !== targetKey) {
    atom = resolveThreadFindAtom(target, progressive);
    setStoredAtom({ key: targetKey, atom });
  }
  const result = useEnvironmentQuery(atom);
  const key = thread
    ? JSON.stringify([thread.environmentId, thread.threadId, normalizedQuery, skillLabels])
    : null;
  const [previous, setPrevious] = useState({
    key,
    data: result.data,
    navigationId,
  });
  if (
    previous.key !== key ||
    (result.data !== null &&
      (!result.isPending || (progressive && previous.data !== result.data)) &&
      (previous.data !== result.data || previous.navigationId !== navigationId))
  ) {
    const response = result.data;
    setPrevious({
      key,
      data: response,
      navigationId,
    });
  }
  return {
    ...result,
    data: key === previous.key && !result.error ? previous.data : null,
    navigationId: previous.navigationId,
    isPending:
      thread !== null &&
      normalizedQuery.length > 0 &&
      (normalizedQuery !== debouncedQuery || result.isPending),
  };
}

function resolveThreadFindAtom(
  target: Parameters<typeof orchestrationEnvironment.threadFind>[0] | null,
  progressive: boolean,
) {
  if (!target) return null;
  return progressive
    ? orchestrationEnvironment.threadFindProgressive(target)
    : orchestrationEnvironment.threadFind(target);
}

import type { LegendListRef } from "@legendapp/list/react";
import { useEffect, useEffectEvent, useRef, type RefObject } from "react";
import type { ThreadFindMatch } from "./threadFind";
import { useThreadFindHighlights } from "./threadFindHighlights";

const FIND_MATCH_VIEW_MARGIN = 96;

type FindEntries = readonly { readonly id: string }[];

interface RevealInputs {
  readonly matchKey: string | null;
  readonly rowIndex: number;
  readonly entries: FindEntries;
  readonly listReady: boolean;
  readonly historyLoading: boolean;
  readonly historyError: string | null;
  readonly contentInsetEndAdjustment: number;
  readonly container: HTMLElement | null;
}

/** Positioning bookkeeping that outlives a render: pending jumps and the pinned match during paging. */
interface RevealState {
  positioning: { key: string; rowIndex: number; entries: FindEntries } | null;
  settledMatch: string | null;
  activeRange: Range | null;
  pagingPosition: { key: string; entries: FindEntries; top: number } | null;
  revealedMatch: string | null;
  positionedEntries: FindEntries | null;
}

/**
 * Brings the active match into view. Async continuations re-enter with the
 * inputs current by then, and stop once the match changes or the list unmounts.
 */
function revealThreadFindMatch(
  range: Range | null,
  inputs: RevealInputs,
  context: {
    readonly state: RevealState;
    readonly listRef: RefObject<LegendListRef | null>;
    readonly readInputs: () => RevealInputs;
  },
): void {
  const { state, listRef, readInputs } = context;
  const {
    matchKey,
    rowIndex,
    entries,
    listReady,
    historyLoading,
    historyError,
    contentInsetEndAdjustment,
    container,
  } = inputs;
  state.activeRange = range;
  if (!matchKey) {
    state.positioning = null;
    state.settledMatch = null;
    state.revealedMatch = null;
    state.pagingPosition = null;
    return;
  }
  const list = listRef.current;
  const stillCurrent = () =>
    list !== null && listRef.current === list && readInputs().matchKey === matchKey;
  const revealAgain = () => revealThreadFindMatch(state.activeRange, readInputs(), context);
  const pagingPosition = state.pagingPosition;
  if (pagingPosition && pagingPosition.key !== matchKey) state.pagingPosition = null;
  if (
    range?.startContainer.isConnected &&
    pagingPosition?.key === matchKey &&
    pagingPosition.entries !== entries
  ) {
    const restore = () => {
      const pinned = state.pagingPosition;
      const currentRange = state.activeRange;
      if (!stillCurrent() || !pinned || !currentRange?.startContainer.isConnected) return;
      const delta = currentRange.getBoundingClientRect().top - pinned.top;
      const scroll = listRef.current?.getState?.().scroll;
      if (Math.abs(delta) >= 1 && typeof scroll === "number")
        listRef.current?.scrollToOffset({ offset: scroll + delta, animated: false });
    };
    pagingPosition.entries = entries;
    restore();
    // The list measures newly inserted activity after the first layout pass.
    requestAnimationFrame(() =>
      requestAnimationFrame(() => {
        restore();
        if (!readInputs().historyLoading && state.pagingPosition === pagingPosition)
          state.pagingPosition = null;
      }),
    );
  }
  if (historyError) state.pagingPosition = null;
  if (state.revealedMatch === matchKey) return;
  if (!listReady || rowIndex < 0) return;
  const materialize = () => {
    const previous = state.positioning;
    if (
      !list ||
      (previous?.key === matchKey && previous.rowIndex === rowIndex && previous.entries === entries)
    )
      return;
    // Activity can insert rows during LegendList layout; retarget pending jumps.
    const request = { key: matchKey, rowIndex, entries };
    state.positioning = request;

    void list
      .scrollToIndex({
        index: rowIndex,
        animated: false,
        viewOffset: FIND_MATCH_VIEW_MARGIN,
      })
      .then(() => {
        if (state.positioning !== request || !stillCurrent()) return;

        state.positionedEntries = entries;
        state.settledMatch = matchKey;
        revealAgain();
      });
  };
  if (!range) {
    if (container) materialize();
    return;
  }

  const groupScroller = range.startContainer.parentElement?.closest<HTMLElement>(
    "[data-tool-group-scroll]",
  );
  if (groupScroller) {
    const rect = range.getBoundingClientRect();
    const viewport = groupScroller.getBoundingClientRect();
    if (rect.top < viewport.top) groupScroller.scrollTop += rect.top - viewport.top - 8;
    else if (rect.bottom > viewport.bottom)
      groupScroller.scrollTop += rect.bottom - viewport.bottom + 8;
  }

  const codeScroller = range.startContainer.parentElement?.closest("pre");
  if (codeScroller) {
    const rect = range.getBoundingClientRect();
    const viewport = codeScroller.getBoundingClientRect();
    if (rect.left < viewport.left) codeScroller.scrollLeft += rect.left - viewport.left - 16;
    else if (rect.right > viewport.right)
      codeScroller.scrollLeft += rect.right - viewport.right + 16;
  }
  const rect = range.getBoundingClientRect();
  const viewport = container?.getBoundingClientRect();
  if (!viewport || rect.height === 0) return;
  const margin = Math.min(
    FIND_MATCH_VIEW_MARGIN,
    Math.max(0, (viewport.height - contentInsetEndAdjustment - rect.height) / 2),
  );
  const top = viewport.top + margin;
  const bottom = viewport.bottom - margin - contentInsetEndAdjustment;
  const delta = rect.top < top ? rect.top - top : rect.bottom > bottom ? rect.bottom - bottom : 0;
  // DOM text can precede settled row sizes; wait before measuring offscreen matches.
  if (
    Math.abs(delta) >= 1 &&
    state.positionedEntries !== entries &&
    state.settledMatch !== matchKey
  ) {
    materialize();
    return;
  }
  const scroll = list?.getState?.().scroll;
  state.positionedEntries = entries;

  state.revealedMatch = matchKey;
  if (historyLoading) state.pagingPosition = { key: matchKey, entries, top: rect.top - delta };
  if (Math.abs(delta) >= 1 && typeof scroll === "number") {
    list?.scrollToOffset({ offset: scroll + delta, animated: false });
    requestAnimationFrame(() => {
      if (!stillCurrent()) return;
      if (
        listRef.current?.getState?.().scroll === scroll &&
        range.getBoundingClientRect().top === rect.top
      )
        return;
      state.revealedMatch = null;
      revealAgain();
    });
  }
}

export function useThreadFindNavigation({
  container,
  query,
  match,
  navigationId,
  rowIndex,
  entries,
  listRef,
  contentInsetEndAdjustment,
  listReady,
  historyControls,
}: {
  container: HTMLElement | null;
  query: string;
  match: ThreadFindMatch | null;
  navigationId: number;
  rowIndex: number;
  entries: FindEntries;
  listRef: RefObject<LegendListRef | null>;
  contentInsetEndAdjustment: number;
  listReady: boolean;
  historyControls?:
    | {
        readonly hasMoreHistory: boolean;
        readonly loading: boolean;
        readonly error: string | null;
        readonly onLoadEarlier: (throughEntryId?: string) => void;
      }
    | undefined;
}) {
  const matchKey = match ? `${navigationId}:${query}:${match.entryId}:${match.occurrence}` : null;
  const historyLoading = historyControls?.loading ?? false;
  const historyError = historyControls?.error ?? null;
  const stateRef = useRef<RevealState>({
    positioning: null,
    settledMatch: null,
    activeRange: null,
    pagingPosition: null,
    revealedMatch: null,
    positionedEntries: null,
  });
  const readInputs = useEffectEvent((): RevealInputs => ({
    matchKey,
    rowIndex,
    entries,
    listReady,
    historyLoading,
    historyError,
    contentInsetEndAdjustment,
    container,
  }));
  // H/Z: stays an effect. The listener compares against the entries rendered at
  // scroll time; the viewport ref callback in MessagesTimeline cannot read
  // them without a latest-ref mirror, and capturing them would re-attach the
  // viewport (observers, citation dismissal) on every streamed entry.
  useEffect(() => {
    if (!container) return;
    const onScroll = () => {
      const state = stateRef.current;
      const position = state.pagingPosition;
      const range = state.activeRange;
      if (
        !position ||
        position.entries !== readInputs().entries ||
        !range?.startContainer.isConnected
      )
        return;
      const rect = range.getBoundingClientRect();
      const viewport = container.getBoundingClientRect();
      if (rect.bottom < viewport.top || rect.top > viewport.bottom) state.pagingPosition = null;
      else position.top = rect.top;
    };
    container.addEventListener("scroll", onScroll, { passive: true });
    return () => container.removeEventListener("scroll", onScroll);
  }, [container]);
  const requestedPagesRef = useRef<{ key: string | null; pages: Set<string> }>({
    key: null,
    pages: new Set(),
  });
  useEffect(() => {
    if (requestedPagesRef.current.key !== matchKey)
      requestedPagesRef.current = { key: matchKey, pages: new Set() };
    if (
      !match ||
      !listReady ||
      rowIndex >= 0 ||
      entries.some((entry) => entry.id === match.entryId)
    )
      return;
    if (!historyControls?.hasMoreHistory || historyControls.loading || historyControls.error)
      return;
    const cursor = entries[0]?.id ?? "first";
    if (requestedPagesRef.current.pages.has(cursor)) return;
    requestedPagesRef.current.pages.add(cursor);

    historyControls.onLoadEarlier(match.entryId);
  }, [entries, historyControls, listReady, match, matchKey, rowIndex]);
  const reveal = useEffectEvent((range: Range | null, inputs: RevealInputs) =>
    revealThreadFindMatch(range, inputs, { state: stateRef.current, listRef, readInputs }),
  );

  useThreadFindHighlights({
    container,
    query,
    activeRowId: match?.entryId ?? null,
    activeOccurrence: match?.occurrence ?? 0,
    onActiveRange: (range) => reveal(range, readInputs()),
  });
  // Positioning also depends on the list: a loaded page or a shifted row must
  // retry the jump for the same selection. Declared after the highlight
  // effects so it reuses the range they just resolved.
  useEffect(() => {
    reveal(stateRef.current.activeRange, {
      matchKey,
      rowIndex,
      entries,
      listReady,
      historyLoading,
      historyError,
      contentInsetEndAdjustment,
      container,
    });
  }, [
    container,
    matchKey,
    rowIndex,
    entries,
    listReady,
    historyLoading,
    historyError,
    contentInsetEndAdjustment,
  ]);
}

import { useLayoutEffect } from "react";
import type { RunId } from "@t3tools/contracts";
import type { TimelineEntry } from "../../session-logic";
import {
  timelineTurnFoldRunIdsByEntryId,
  type MessagesTimelineRow,
  type TimelineLatestRun,
} from "./MessagesTimeline.logic";
import type { ThreadFindPositionReader } from "./threadFind";
import { attachThreadFindTimeline } from "./threadFindStore";
import { readThreadFindPosition } from "./threadFindPosition";

/** Hands thread find how to read the find position of this timeline's viewport. */
export function useThreadFindPositionReader({
  threadKey,
  navigate,
  timelineViewportElement,
  findFoldRunIds,
  timelineEntries,
  latestRun,
  runningRunId,
  isWorking,
  runlessWorkActive,
  rows,
  contentInsetEndAdjustment,
}: {
  readonly threadKey: string;
  readonly navigate: () => void;
  readonly timelineViewportElement: HTMLDivElement | null;
  readonly findFoldRunIds: ReadonlyMap<string, RunId> | null;
  readonly timelineEntries: ReadonlyArray<TimelineEntry>;
  readonly latestRun: TimelineLatestRun | null;
  readonly runningRunId: RunId | null;
  readonly isWorking: boolean;
  readonly runlessWorkActive: boolean;
  readonly rows: MessagesTimelineRow[];
  readonly contentInsetEndAdjustment: number;
}) {
  // Layout effect so a find opened right after a thread switch reads this viewport.
  useLayoutEffect(() => {
    if (!timelineViewportElement) return;
    const read: ThreadFindPositionReader = (query) => {
      const foldRunIds =
        findFoldRunIds ??
        timelineTurnFoldRunIdsByEntryId({
          timelineEntries,
          latestRun,
          runningRunId,
          isWorking,
          runlessWorkActive,
        });
      const entryById = new Map(timelineEntries.map((entry) => [entry.id, entry]));
      return readThreadFindPosition(
        timelineViewportElement,
        query,
        (rowId) => {
          if (entryById.has(rowId)) return rowId;
          const rowIndex = rows.findIndex((row) => row.id === rowId);
          for (const row of rows.slice(Math.max(0, rowIndex))) {
            if (row.kind !== "turn-fold" && row.kind !== "attempt-fold") {
              if (row.kind === "work") return row.groupedEntries[0]?.id;
              if (row.kind === "work-live") return row.groupedEntries[0]?.id;
              if (row.kind === "work-toggle") {
                const anchor = timelineEntries.find(
                  (entry) => row.groupId === `work-group:${entry.id}`,
                );
                if (anchor) return anchor.id;
              }
              const entry = entryById.get(row.kind === "assistant-meta" ? row.message.id : row.id);
              if (
                entry &&
                (entry.kind === "message" ||
                  entry.kind === "proposed-plan" ||
                  entry.kind === "work")
              )
                return entry.id;
              continue;
            }
            const entry = timelineEntries.find((entry) => {
              const runId =
                row.kind === "turn-fold"
                  ? foldRunIds.get(entry.id)
                  : entry.kind === "message"
                    ? entry.message.runId
                    : entry.kind === "proposed-plan"
                      ? entry.proposedPlan.runId
                      : null;
              return (
                runId === row.runId &&
                (entry.kind !== "message" || entry.message.role === "assistant") &&
                (row.kind !== "attempt-fold" || entry.attempt?.id === row.attemptId)
              );
            });
            if (
              entry &&
              (entry.kind === "message" || entry.kind === "proposed-plan" || entry.kind === "work")
            )
              return entry.id;
          }
          return undefined;
        },
        contentInsetEndAdjustment,
      );
    };
    return attachThreadFindTimeline({ threadKey, readPosition: read, navigate });
  }, [
    contentInsetEndAdjustment,
    findFoldRunIds,
    isWorking,
    navigate,
    threadKey,
    latestRun,
    rows,
    runlessWorkActive,
    runningRunId,
    timelineEntries,
    timelineViewportElement,
  ]);
}

